package net.officefloor.hq.app.auditview;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class RespondWithAuditLines {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "name", required = false) String name, Audit audit,
            ObjectResponse<List<String>> response) {
        response.send(audit.lines(sheetId.trim(), name));
    }
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { SheetPanel } from '../../slots/defs/sheetPanel';

/** The audit viewer: the sheet's audit lines exactly as the audit file holds them, newest first. With a name in the
 *  filter, only the lines about that person (name=<it> or person=<it>, case and surrounding spaces ignored). */
function AuditView({ sheetId }: { sheetId: string }) {
  const [filter, setFilter] = useState('');
  const [lines, setLines] = useState<string[]>([]);
  const [error, setError] = useState('');

  const show = useMutation({
    mutationFn: (name: string) =>
      getJson<string[]>(
        `/api/sheets/${encodeURIComponent(sheetId)}/audit?name=${encodeURIComponent(name)}`,
      ),
    onSuccess: (found) => setLines(found),
    onError: (e: Error) => setError(e.message || 'The audit lines could not be read.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setLines([]);
    show.mutate(filter.trim());
  };

  return (
    <section data-testid="audit-view">
      <h3>Audit</h3>
      <form onSubmit={submit}>
        <label>
          Person{' '}
          <input
            data-testid="audit-filter"
            value={filter}
            onChange={(e) => {
              setFilter(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="audit-show" disabled={show.isPending}>
          Show
        </button>
        {error && <p data-testid="audit-error">{error}</p>}
      </form>
      <ol data-testid="audit-lines">
        {lines.map((line, i) => (
          <li key={i} data-testid="audit-line">
            {line}
          </li>
        ))}
      </ol>
    </section>
  );
}

// Keyed by sheet, so a filter or the lines shown never carry over to another sheet.
export const contribution = SheetPanel.fill({
  order: 40,
  Component: ({ sheetId }) => <AuditView key={`audit-view-${sheetId}`} sheetId={sheetId} />,
});
-- A person's position in the sheet's list: the list (and everything worked out in list order) runs by position, lowest
-- first. A new person (added, imported or transferred in) goes after everyone on the sheet; moving a person up or down
-- swaps positions with their neighbour. Positions may have gaps (a person merged away or transferred out leaves one).
-- People stored before keep the order they were added in. Kept in the person's history too (see V39). The journal
-- trigger is made again around the change, as in V41.
DROP TRIGGER person_journal;
ALTER TABLE person ADD COLUMN list_position BIGINT;
UPDATE person SET list_position = id;
ALTER TABLE person ALTER COLUMN list_position SET NOT NULL;
ALTER TABLE person_history ADD COLUMN list_position BIGINT;
UPDATE person_history SET list_position = id;
CREATE TRIGGER person_journal AFTER INSERT, UPDATE, DELETE ON person FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';

