import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { usePersonError } from './usePersonError';
import { useUser } from '../session/useUser';
import { sheetKey } from '../sheet/sheetQuery';

/**
 * The control that transfers the person to another sheet by id (a steward only; not a retired person, not this
 * sheet). The person leaves this sheet with their claims, so every figure of the sheet is re-read.
 */
function PersonTransfer({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [to, setTo] = useState('');
  const [, setError] = usePersonError(personId);
  const once = useSubmitOnce();
  const transfer = useMutation({
    mutationFn: (toSheetId: string) =>
      postJson<unknown>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/transfer`, { toSheetId }, user),
    onSuccess: async () => {
      setTo('');
      setError('');
      await queryClient.invalidateQueries({ queryKey: sheetKey(sheetId) });
    },
    onError: () => setError('The person could not be transferred.'),
  });

  return (
    <td>
      <input
        data-testid="person-transfer-to"
        placeholder="sheet id"
        value={to}
        onChange={(e) => {
          setTo(e.target.value);
          setError('');
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-transfer"
        disabled={transfer.isPending}
        onClick={() => {
          setError('');
          if (to.trim() === '') {
            setError('Give the id of the sheet to transfer to.');
            return;
          }
          once(() => transfer.mutateAsync(to.trim()));
        }}
      >
        Transfer
      </button>
    </td>
  );
}

// The row's `person-error` is shown by the hold cell, shared by every cell acting on the person.
export const contributions = [
  PersonHeaders.fill({ order: 23.5, Component: () => <th>Transfer</th> }),
  PersonCells.fill({ order: 23.5, Component: PersonTransfer }),
];
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/**
 * `version` is raised on every edit; an edit names the version it loaded. `retiredFrom` (yyyy-mm-dd) is
 * set once the person is retired, which they are at once, whatever the date; null otherwise. `held` is whether
 * they have any hold; `holds` are their holds by from-date: their OPEN claims dated within one, unless bound by a
 * statement, count in no live total. `terms` are their own terms in days, which come before those of their grade
 * and of the sheet; null for none. `contact` is their contact, trimmed and lower-cased, unique on the sheet; null
 * for none. `aliases` are their aliases, sorted as names are compared (ignoring case); the quick-add bar and the
 * paste box find a person by one as well as by the name. A name or alias is unique across the sheet's tree (its
 * ancestors and descendants); `clashing` is whether the person's name or an alias is used by someone else there all
 * the same (they were on the sheet before), which refuses every edit of them until a rename frees them.
 */
export type Person = { id: number; name: string; grade: Grade; grades: Graded[]; version: number; retiredFrom: string | null; held: boolean; holds: Held[]; terms: number | null; contact: string | null; aliases: string[]; clashing: boolean };

/** A hold from `from` to `to` inclusive (yyyy-mm-dd); `to` is null when it has no end. */
export type Held = { from: string; to: string | null };

/** Whether the date (yyyy-mm-dd) falls within any of the person's holds. */
export function heldOn(person: Person | undefined, date: string): boolean {
  return (person?.holds ?? []).some((h) => h.from <= date && (h.to === null || date <= h.to));
